describe('Row Badge Count Display', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should display badge count for selected rows', () => {
    // Intercept the API call to get table data
    cy.intercept('GET', '/api/table-data').as('getTableData');
    cy.wait('@getTableData');

    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Select the first row
    cy.get('[data-testid="row-1"]').click();

    // Verify row is selected
    cy.get('[data-testid="row-1"]').should('have.class', 'selected');

    // Verify badge count is displayed
    cy.get('[data-testid="badge-count"]').should('be.visible');
    cy.get('[data-testid="badge-count"]').should('contain', '1');

    // Select the second row
    cy.get('[data-testid="row-2"]').click();

    // Verify multiple rows are selected
    cy.get('[data-testid="row-1"]').should('have.class', 'selected');
    cy.get('[data-testid="row-2"]').should('have.class', 'selected');

    // Verify badge count updates
    cy.get('[data-testid="badge-count"]').should('contain', '2');

    // Verify badge count is displayed for all selected rows
    cy.get('[data-testid="badge-count"]').should('be.visible');
    cy.get('[data-testid="badge-count"]').should('contain', '2');
  });

  it('should not display badge count when no rows are selected', () => {
    // Intercept the API call to get table data
    cy.intercept('GET', '/api/table-data').as('getTableData');
    cy.wait('@getTableData');

    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify no rows are selected
    cy.get('[data-testid="row-1"]').should('not.have.class', 'selected');

    // Verify badge count is not displayed
    cy.get('[data-testid="badge-count"]').should('not.exist');

    // Verify no badge count text is present
    cy.get('[data-testid="no-selection-message"]').should('be.visible');
    cy.get('[data-testid="no-selection-message"]').should('contain', 'Select rows to see badge count');

    // Verify no badge count is shown when no rows are selected
    cy.get('[data-testid="badge-count"]').should('not.exist');
  });
});
